% NetHorizon CVRPTW
int: n = 50;
int: vehicles = 6;
int: capacity = 200;
array[1..n] of int: demand;
solve minimize total_distance + 45*lateness_tenths;

include "cumulative.mzn";
int: jobs = 20;
int: machines = 5;
var 0..400: makespan;
constraint makespan <= 312;
solve minimize makespan;

float: hold = 1.20; float: setup = 450;
array[1..8] of float: demand;
var 0.0..10000.0: inventory;
solve minimize hold*inventory + setup*n_setups;

int: n = 12; int: budget = 2400000;
array[1..n] of int: cost;
array[1..n] of int: npv;
array[1..n] of var bool: z;
constraint z[3] /\ z[4] = false;
solve maximize sum(i in 1..n)(npv[i]*z[i]);

int: p = 8; int: sites = 40; int: stores = 120;
array[1..sites] of var bool: open;
constraint sum(open) = p;
solve minimize total_distance;

int: G = 6; int: T = 24; float: reserve = 0.12;
array[1..G,1..T] of var bool: on;
solve minimize fuel + startup;

int: kerf = 32; % tenths of mm
int: sheets_ub = 17;
constraint no_overlap_2d(x, dx, y, dy);
solve minimize n_sheets;

include "global_cardinality.mzn";
int: staff = 42;
int: days = 14;
constraint max_nights <= 3;
solve satisfy;
